{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Colon capsule endoscopy (CCE) has emerged as a promising alternative for investigating lower gastrointestinal symptoms. However, its adoption has been limited due to concerns about cost-­ effectiveness, significantly influenced by follow-­ up endoscopy rates (FERs).",
      "reason": "The text describes the current state of knowledge regarding CCE (promising alternative) and the important uncertainty/barrier (limited adoption due to concerns about cost-effectiveness and FERs)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Understanding CCE's FERs is crucial for its integration into routine clinical practice. We synthesised the evidence to evaluate the overall rate of further investigation in CCE.",
      "reason": "The text explicitly states the importance of understanding FERs for clinical practice and the need to synthesize evidence to evaluate these rates."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not an update or replication of a previous systematic review, and the authors do not frame the current review as a response to existing similar reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review evaluates follow-up endoscopy rates (a process/outcome metric) rather than the intervention effects of CCE itself."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not involve a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
}

{
