{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The inclusion criteria for the full-­ text review were: 1. Follow-­ up investigations (reinvestigation) prompted by incomplete procedures, poor bowel preparation, or any detected GI pathology in the terminal ileum or colon. 2. Any clinical indication for CCE. 3. Studies with more than 10 participants. 4. The FER did not need to be explicitly stated as the study's primary or secondary endpoint but could be calculated from the available raw data.",
      "reason": "The manuscript specifies inclusion criteria regarding study design, population (CCE patients), and follow-up requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "There were no language restrictions, and all the non-­ English articles were screened with the intention of being translated and included if they met the predefined inclusion criteria. ... However, conference abstracts were excluded due to their high risk of bias. Similarly, review articles, systematic reviews, editorials, study protocols, case reports, and small case series or studies with 10 or fewer participants were excluded.",
      "reason": "The manuscript specifies report characteristics including language, publication status (excluding abstracts, reviews, etc.), and date range (in text_6)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly distinguish between exclusion due to outcomes not being measured versus exclusion due to results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "To explore potential sources of heterogeneity, meta-­ regression was performed, analysing prespecified subgroups or covariates, including capsule type, different CCE indications, age, sex, and the proportion of participants with adequate bowel cleansing (%) and complete transit rates (%).",
      "reason": "The manuscript specifies the groups and covariates used for synthesis (meta-regression and subgroup analysis)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Exclusion criteria primarily focused on studies where follow-­ up investigations were conducted for upper GI findings, as these conditions would not typically be identified during colonoscopy, the gold standard for comparison of CCE FERs.",
      "reason": "The manuscript provides a rationale for the exclusion of studies involving upper GI findings."
    }
  ],
  "confidence": 100
}

